import React, { useEffect, useState } from "react";
import "./Toast.scss";
import clsx from "clsx";
import { Alert } from "../alert";
import { SvgMpaIcon } from "../..";

type ContentType = {
  label?: string;
  message: string;
};

export interface ToastProps {
    /**
     * Unique identifier for the toast component, useful for testing or analytics.
     */
    id: string;
    /**
     * Visual style variant of the alert
     * @default "white"
     */
    variant?: "white" | "colour";

    /**
     * Color scheme indicating alert type/severity
     */
    colour?:  "success" | "error" | "info" | "warn";

     /**
     * Text label for the action button (optional)
     */
    action?: string;

    /**
     * Callback function triggered when the toast is closed (either by auto-dismiss or user action).
     */
    onClose?: () => void;

    /**
     * Optional callback function triggered when the action button is clicked.
     */
    onAction?: () => void;

    /**
     * Size variant of the alert component
     * @default "small"
     */
    size?: "small" | "medium";
    /**
     * Content to display in the alert. Array enables paginated alert
     */
    content: ContentType | ContentType[];
    /**
     * Displays default semantic icon
     * @default true
     */
    showSemanticIcon?: boolean;

    /**
     * Custom className that can be passed to the element for overriding styling.
     */
    className?: string;
    /**
     * SVG React Component to be displayed as the alert close icon.
     */
    trailingIcon?: keyof typeof SvgMpaIcon | string;

    /**
     * Position of the toast on the screen.
     */
    position?:   "top-center" | "top-right" | "off-center" | "bottom-center" | "bottom-right";  
    /**
     * Duration (in milliseconds) before the toast auto-dismisses, if enabled.
     */
    duration?: number;
  }
  
const Toast: React.FC<ToastProps> = ({
  id,
  variant = "white",
  colour,
  onClose,
  action,
  onAction,
  size = "small",
  content,
  showSemanticIcon = true,
  className,
  trailingIcon,
  position = "top-right",
  duration = 5000,
}) => {
  const [visible, setVisible] = useState(true);

  const handleClose = () => {
    setVisible(false);
    onClose?.();
  };


  useEffect(() => {
    const timer = setTimeout(() => {
      handleClose();
    }, duration);
    return () => {
      clearTimeout(timer);
    }
  }, [duration]);


  if (!visible) return null;

  const positionClass = `toast-${position}`; 
  
  return (
    <div className={clsx("toast-wrapper", positionClass)}>
      <Alert 
          id={id}
          variant= {variant}
          colour= {colour}
          size={size}
          content={content}
          showSemanticIcon={showSemanticIcon}
          className={className}
          trailingIcon={trailingIcon}
          action={action}
          onClose={handleClose}
          onAction={onAction}
      />
    </div>
);

};

export default Toast;
